#!/usr/bin/env python3
"""SPROCKET W26 CPU research source (lossless gzip transport).

Run --print-source to inspect original 19,165-byte Python source; otherwise
the SHA-verified script executes normally. Requires W24 and W25 original ZIPs.
This trains only a small auxiliary policy; no root-model/LoRA updates.
"""
import base64,gzip,hashlib,sys
_SOURCE=""""""
def _source():
    data=gzip.decompress(base64.b64decode(_SOURCE))
    assert hashlib.sha256(data).hexdigest()=="1e27211f8011202bdb519cab401aa6720d0aefde50e636ff71ac6c338df53d85"
    return data
if __name__=="__main__" and sys.argv[1:]==["--print-source"]:
    sys.stdout.buffer.write(_source())
else:
    exec(compile(_source().decode("utf-8"),__file__,"exec"),globals())
